from collections import OrderedDict


class TTLCache:
    """A capacity-bounded cache whose entries expire after ``ttl_seconds``.

    Recency is tracked with an ``OrderedDict``: the leftmost item is the
    least-recently-used one. ``get`` on a live entry moves it to the most
    recently used position; ``put`` inserts/updates at the most recently
    used position and evicts from the left once over capacity.
    """

    def __init__(self, capacity, ttl_seconds, clock):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.ttl_seconds = ttl_seconds
        self.clock = clock
        # key -> (value, inserted_at)
        self._entries = OrderedDict()

    def _is_expired(self, inserted_at):
        return self.clock() - inserted_at >= self.ttl_seconds

    def _purge_expired(self):
        expired = [k for k, (_, ts) in self._entries.items() if self._is_expired(ts)]
        for key in expired:
            del self._entries[key]

    def get(self, key):
        entry = self._entries.get(key)
        if entry is None:
            return None
        value, inserted_at = entry
        if self._is_expired(inserted_at):
            del self._entries[key]
            return None
        self._entries.move_to_end(key)
        return value

    def put(self, key, value):
        now = self.clock()
        if key in self._entries:
            del self._entries[key]
        self._entries[key] = (value, now)
        if len(self._entries) > self.capacity:
            self._purge_expired()
        while len(self._entries) > self.capacity:
            self._entries.popitem(last=False)

